const rows = $input.all().map(i => i.json);
const trig = $('Execute Workflow Trigger').first().json;
const lines = rows.filter(r => r.status).map(r => {
  const cur = r.currency || 'INR';
  const valStr = cur === 'INR' ? `\u20b9${Number(r.value).toLocaleString('en-IN')}` : `${cur} ${Number(r.value).toLocaleString('en-US')}`;
  return `\u2022 ${r.status}: ${r.cnt} lead(s) \u2014 ${valStr}`;
});
const totalsByCur = {};
for (const r of rows) {
  if (!r.status) continue;
  const cur = r.currency || 'INR';
  totalsByCur[cur] = (totalsByCur[cur] || 0) + Number(r.value || 0);
}
const totalLines = Object.entries(totalsByCur).map(([cur, tot]) => {
  const valStr = cur === 'INR' ? `\u20b9${Number(tot).toLocaleString('en-IN')}` : `${cur} ${Number(tot).toLocaleString('en-US')}`;
  return `Total active pipeline: ${valStr}`;
}).join('\n') || 'Total active pipeline: \u20b90';
return [{ json: { chatId: trig.chatId, text: `\ud83d\udcca <b>Pipeline</b>\n${lines.join('\n') || 'No active leads.'}\n\n${totalLines}` } }];

const rows = $input.all().map(i => i.json).filter(r => r && (r.won_count !== undefined || r.currency));
const trig = $('Execute Workflow Trigger').first().json;
if (rows.length === 0 || (!rows[0].won_count && !rows[0].won_value)) {
  return [{ json: { chatId: trig.chatId, text: `\ud83d\udcb0 <b>Revenue \u2014 This Month</b>\nDeals won: 0\nRevenue: \u20b90` } }];
}
const lines = rows.map(r => {
  const cur = r.currency || 'INR';
  const valStr = cur === 'INR' ? `\u20b9${Number(r.won_value).toLocaleString('en-IN')}` : `${cur} ${Number(r.won_value).toLocaleString('en-US')}`;
  return `Deals won: ${r.won_count}\nRevenue: ${valStr}`;
});
return [{ json: { chatId: trig.chatId, text: `\ud83d\udcb0 <b>Revenue \u2014 This Month</b>\n${lines.join('\n\n')}` } }];

const r = $input.first().json;
const trig = $('Execute Workflow Trigger').first().json;
const winRate = (Number(r.won) + Number(r.lost)) > 0 ? ((Number(r.won) / (Number(r.won) + Number(r.lost))) * 100).toFixed(1) : '0.0';
return [{ json: { chatId: trig.chatId, text: `👥 <b>Lead Stats</b>
Total leads: ${r.total}
Active: ${r.active}
Won: ${r.won}
Lost: ${r.lost}
Win rate: ${winRate}%` } }];
